sys_script_fix.script:
(function() {
  var P = 'x_2206627_er_tri_0_patient';
  var E = 'x_2206627_er_tri_0_encounter';
  var V = 'x_2206627_er_tri_0_vitals';
  var A = 'x_2206627_er_tri_0_triage_assessment';

  // 1. Test patient (reused on later runs)
  var p = new GlideRecord(P);
  if (!p.get('patient_last_name', 'StubTest')) {
    p.initialize();
    p.setValue('patient_first_name', 'E2E');
    p.setValue('patient_last_name', 'StubTest');
    var dob = new GlideDate();
    dob.addYearsLocalTime(-58);
    p.setValue('date_of_birth', dob);
    p.setValue('sex', 'male');
    p.setValue('diabetic', true);
    p.insert();
  }

  // 2. New encounter and vitals
  var e = new GlideRecord(E);
  e.initialize();
  e.setValue('patient', p.getUniqueValue());
  e.setValue('chief_complaint', 'Bad indigestion');
  e.setValue('triage_note', '[E2E] Stub end-to-end test');
  var eid = e.insert();
  gs.info('Encounter: ' + e.getValue('number') + ' (age ' + e.getValue('age_at_arrival') + ')');

  var v = new GlideRecord(V);
  v.initialize();
  v.setValue('encounter', eid);
  v.setValue('heart_rate', 108);
  v.setValue('systolic_bp', 150);
  v.setValue('diastolic_bp', 92);
  v.setValue('spo2', 96);
  v.insert();

  // 3. Run triage
  var svc = new ERTriageService();
  var aid = svc.runTriage(eid);
  if (!aid) { gs.error('runTriage returned null'); return; }

  var a = new GlideRecord(A);
  a.get(aid);
  gs.info('Assessment: ' + a.getValue('number'));
  gs.info('Rule / LLM / Suggested ESI: ' + a.getValue('rule_esi') + ' / ' +
    a.getValue('llm_esi') + ' / ' + a.getValue('suggested_esi'));
  gs.info('Disagreement: ' + a.getValue('disagreement') +
    ' | AI available: ' + a.getValue('ai_available') + ' | Model: ' + a.getValue('model'));

  // 4. Accept and check the encounter
  gs.info('Accept recorded: ' + svc.recordDecision(aid, 'accepted'));
  e.get(eid);
  gs.info('Encounter ESI: ' + e.getValue('current_esi') + ' | Status: ' +
    e.getValue('status') + ' | Area: ' + e.getValue('assigned_area'));
})();
